  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Retires the person from the date asked (the sheet's today when none): they count as retired at once. */
public class RetirePerson {
    public void retire(@Val RetireRequest request, @Val Person person, SheetRepository sheets,
            PersonRepository people) {
        person.setRetiredFrom(request.from() != null ? request.from()
                : sheets.today(person.getSheetId()).toString());
        people.updateRetired(person);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the retirement date: null when blank (the sheet's today); a date that is not a date is refused. */
public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<RetireRequest> body)
            throws InvalidPersonException {
        String from = request == null || request.from() == null ? "" : request.from().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date: " + from);
            }
        }
        body.set(new RetireRequest(from.isEmpty() ? null : from));
    }
}
package net.officefloor.hq.app.person;

/** Body of a retirement: the date the person is retired from (blank: the sheet's today). */
public record RetireRequest(String from) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a retirement that went through is recorded. */
public class RecordPersonRetired {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, Audit audit) {
        audit.record("PERSON_RETIRED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " from=" + person.getRetiredFrom());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Names the patron for the person: refused (nothing written) when the patron is the person
 *  themselves, is not on the sheet, or is already one of their patrons. */
public class AddPatron {
    public void add(@RequestParam(name = "by", required = false) String by,
            @Val PatronRequest request, @Val Person person, PersonRepository people,
            Out<Patron> added) throws InvalidPersonException {
        long patronId = request.patronId();
        if (patronId == person.getId()) {
            throw new InvalidPersonException("A person cannot be their own patron");
        }
        Person patron = people.find(person.getSheetId(), patronId);
        if (patron == null) {
            throw new InvalidPersonException("No such person on the sheet: " + patronId);
        }
        if (person.getPatronIds().contains(patronId)) {
            throw new InvalidPersonException(patron.getName() + " is already a patron");
        }
        people.addPatron(person, patron, by == null ? "" : by);
        added.set(new Patron(patron));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the patron asked for: refused when none is named. */
public class ValidatePatron {
    public void validate(@RequestBody PatronRequest request, Out<PatronRequest> body)
            throws InvalidPersonException {
        if (request == null || request.patronId() == null) {
            throw new InvalidPersonException("No patron named");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the patron just named (PATRON_ADDED). */
public class RecordPatronAdded {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, @Val Patron patron, Audit audit) {
        audit.record("PATRON_ADDED sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " patron=" + patron.person().getName());
    }
}
package net.officefloor.hq.app.person;

/** The person just named as a patron, for the audit line. */
public record Patron(Person person) {
}
package net.officefloor.hq.app.person;

/** The alias just given to a person, for the audit line. */
public record Alias(String alias) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<Person> response) {
        response.send(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId,
            @PathVariable("personId") long personId, PersonRepository people,
            Out<Person> person) throws PersonNotFoundException {
        Person found = people.find(sheetId.trim(), personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}

