20	
21	const EMPTY: PersonInput = { name: '', grade: 'A', gradeFrom: '', terms: '', contact: '' };
22	
23	/** The people on the sheet: a form that adds a person or edits one, and the list in added order,
24	 *  each with their grade in force on the sheet's today, their claimed total, their due-total (the sum of their claims' due figures, at most the sheet's cap, with the excess above it, and split into settled and open (see `splitDues`); n/a
25	 *  when their grade has no rate on the sheet's today and no settled or stated claim keeps a figure),
26	 *  their statements (a button that takes one, now or as of the date typed beside it, a button that cancels the last, the count, the last one's due-total and date), whether
27	 *  they are retired and from when (with a date and a button that retires them), whether they have
28	 *  any hold, their holds (each from a date to an optional date, with dates and a button that adds one;
29	 *  their OPEN claims dated within a hold, and not bound by a statement, count in no total), their
30	 *  patrons (names sorted, with a picker that names one more), their aliases (sorted as names are
31	 *  compared, with an entry and a button that adds one) and backing (see `backing`), and
32	 *  their due-total for each period (see `personPeriodDue`), the due of their open claims by age (see `agedDues`), their overdue claims (OPEN ones past their due-by; the count and their due added up) and their claims, each
33	 *  with a checkbox that selects it for a button that opens the selected claims together.
34	 *  Each person has a checkbox that selects them for a grade given to the selected people together.
35	 *  Retired people are left out of the list unless "show retired" is on; their claims still count.
36	 *  Whether each person is active (see `isActive`).
37	 *  Whether the signed-in user watches each person, with a button that starts or stops it.
38	 *  A button exports everyone, retired people included, as a CSV file. */
39	export function People({ sheetId, user }: { sheetId: string; user: string }) {
40	  const queryClient = useQueryClient();
41	  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
42	  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
43	  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
44	  const watches = useQuery({ queryKey: watchesKey(sheetId, user), queryFn: () => listWatches(sheetId, user) });
45	  const watched = new Set(watches.data ?? []);
46	  const periods = useQuery({ queryKey: periodsKey(sheetId), queryFn: () => listPeriods(sheetId) });
47	  const floor = useFloor(sheetId);
48	  const today = useSheetToday(sheetId, user);
49	  const cap = useCap(sheetId, today);
50	  const charges = useLate(sheetId, today);
51	  const byGrade = rateByGrade(rates.data, today);
52	  const [form, setForm] = useState<PersonInput>(EMPTY);
53	  // The person being edited and the version of them the form loaded.
54	  const [editing, setEditing] = useState<{ id: number; version: number } | null>(null);
55	  const [showRetired] = useShowRetired();
56	  // The retirement date typed on each person's row (blank: the sheet's today).
57	  const [retireDates, setRetireDates] = useState<Record<number, string>>({});
58	  // The statement date typed on each person's row (blank: the statement is taken now).
59	  const [asOfDates, setAsOfDates] = useState<Record<number, string>>({});
60	  // The hold dates typed on each person's row (blank from: the sheet's today; blank to: open-ended).
61	  const [holdDates, setHoldDates] = useState<Record<number, { from: string; to: string }>>({});
62	  // The patron picked on each person's row (blank: none picked).
63	  const [patronPicks, setPatronPicks] = useState<Record<number, string>>({});
64	  // The alias typed on each person's row.
65	  const [aliasInputs, setAliasInputs] = useState<Record<number, string>>({});
66	  // The people selected for a bulk grade.
67	  const [selectedPeople, setSelectedPeople] = useState<ReadonlySet<number>>(new Set());
68	  const selectPerson = (id: number, on: boolean) => setSelectedPeople((s) => {
69	    const next = new Set(s);
70	    if (on) next.add(id); else next.delete(id);
71	    return next;
72	  });
73	  // The claims selected for a bulk action.
74	  const [selected, setSelected] = useState<ReadonlySet<number>>(new Set());
75	  const select = (id: number, on: boolean) => setSelected((s) => {
76	    const next = new Set(s);
77	    if (on) next.add(id); else next.delete(id);
78	    return next;
79	  });
80	
81	  const save = useMutation({
82	    mutationFn: async (v: { editing: { id: number; version: number } | null; input: PersonInput }) => {
83	      if (v.editing === null) return addPerson(sheetId, user, v.input);
84	      try {
85	        return await updatePerson(sheetId, user, v.editing.id, v.editing.version, v.input);
86	      } catch (e) {
87	        // Someone else saved the person since the form loaded them: show what is stored now. The
88	        // form keeps the version it loaded, so a save goes through once the editor is opened again.
89	        if (e instanceof HttpError && e.status === 409) {
90	          const now = await queryClient.fetchQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId), staleTime: 0 });
91	          const current = now.find((p) => p.id === v.editing?.id);
92	          if (current) setForm({ name: current.name, grade: current.grade, gradeFrom: '', terms: current.terms === null ? '' : String(current.terms), contact: current.contact ?? '' });
93	        }
94	        throw e;
95	      }
96	    },
97	    onSuccess: () => {
98	      setForm(EMPTY);
99	      setEditing(null);
100	      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
101	    },
102	    // A refused edit (not one someone else saved meanwhile) closes the editor, its error still
103	    // showing, and leaves the form ready for an add; the person is as they were.
104	    onError: (e, v) => {
105	      if (v.editing !== null && !(e instanceof HttpError && e.status === 409)) {
106	        setForm(EMPTY);
107	        setEditing(null);
108	      }
109	    },
110	  });
111	
112	  const submitOnce = useSubmitOnce();
113	  const stateOnce = useSubmitOnce();
114	
115	  // The person whose last statement was refused; cleared by the next statement taken here, or by
116	  // the statement date typed.
117	  const statement = useMutation({
118	    mutationFn: (v: { id: number; asof: string }) => takeStatement(sheetId, user, v.id, v.asof),
119	    // The date typed goes once the statement is taken or refused, so the next one is taken now unless
120	    // dated again.
121	    onError: (_, v) => setAsOfDates((d) => ({ ...d, [v.id]: '' })),
122	    onSuccess: (_, v) => {
123	      setAsOfDates((d) => ({ ...d, [v.id]: '' }));
124	      return Promise.all([
125	        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
126	        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
127	      ]);
128	    },
129	  });
130	
131	  // The person whose last statement cancel was refused; cleared by the next action on the row.
132	  const unstatement = useMutation({
133	    mutationFn: (id: number) => cancelStatement(sheetId, user, id),
134	    onSuccess: () => Promise.all([
135	      queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
136	      queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
137	    ]),
138	  });
139	
140	  // The person whose last retirement was refused; cleared by the next action on the row.
141	  const retirement = useMutation({
142	    mutationFn: (v: { id: number; from: string }) => retirePerson(sheetId, user, v.id, v.from),
143	    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
144	  });
145	
146	  // The person whose last hold was refused; cleared by the next action on the row.
147	  const holding = useMutation({
148	    mutationFn: (v: { id: number; from: string; to: string }) => holdPerson(sheetId, user, v.id, v.from, v.to),
149	    onSuccess: () => Promise.all([
150	      queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
151	      queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
152	    ]),
153	  });
154	
155	  // The person whose last patron added was refused; cleared by the next action on the row.
156	  const patronage = useMutation({
157	    mutationFn: (v: { id: number; patronId: number }) => addPatron(sheetId, user, v.id, v.patronId),
158	    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
159	  });
160	
161	  // The person whose last alias added was refused; cleared by the next action on the row.
162	  const aliasing = useMutation({
163	    mutationFn: (v: { id: number; alias: string }) => addAlias(sheetId, user, v.id, v.alias),
164	    onSuccess: (_, v) => {
165	      setAliasInputs((d) => ({ ...d, [v.id]: '' }));
166	      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
167	    },
168	  });
169	
170	  // The person whose last watch was refused; cleared by the next action on the row.
171	  const watching = useMutation({
172	    mutationFn: (v: { id: number; on: boolean }) => watchPerson(sheetId, user, v.id, v.on),
173	    onSuccess: () => queryClient.invalidateQueries({ queryKey: watchesKey(sheetId, user) }),
174	  });
175	
176	  const resetRowActions = () => {
177	    statement.reset();
178	    unstatement.reset();
179	    watching.reset();
180	    retirement.reset();
181	    holding.reset();
182	    patronage.reset();
183	    aliasing.reset();
184	  };
185	
186	  const state = (id: number) => {
187	    stateOnce(() => {
188	      resetRowActions();
189	      return statement.mutateAsync({ id, asof: asOfDates[id] ?? '' });
190	    });
191	  };
192	
193	  const unstate = (id: number) => {
194	    stateOnce(() => {
195	      resetRowActions();
196	      return unstatement.mutateAsync(id);
197	    });
198	  };
199	
200	  const watch = (id: number, on: boolean) => {
201	    stateOnce(() => {
202	      resetRowActions();
203	      return watching.mutateAsync({ id, on });
204	    });
205	  };
206	
207	  const retire = (id: number) => {
208	    const from = retireDates[id] ?? '';
209	    stateOnce(() => {
210	      resetRowActions();
211	      return retirement.mutateAsync({ id, from });
212	    });
213	  };
214	
215	  const hold = (id: number) => {
216	    const { from = '', to = '' } = holdDates[id] ?? {};
217	    stateOnce(() => {
218	      resetRowActions();
219	      return holding.mutateAsync({ id, from, to });
220	    });
221	  };
222	
223	  const changeHold = (id: number, patch: Partial<{ from: string; to: string }>) => {
224	    setHoldDates((d) => ({ ...d, [id]: { from: '', to: '', ...d[id], ...patch } }));
225	    holding.reset();
226	  };
227	
228	  const patronize = (id: number) => {
229	    const patronId = Number(patronPicks[id] ?? '');
230	    stateOnce(() => {
231	      resetRowActions();
232	      return patronage.mutateAsync({ id, patronId });
233	    });
234	  };
235	
236	  const alias = (id: number) => {
237	    const typed = aliasInputs[id] ?? '';
238	    stateOnce(() => {
239	      resetRowActions();
240	      return aliasing.mutateAsync({ id, alias: typed });
241	    });
242	  };
243	
244	  const change = (patch: Partial<PersonInput>) => {
245	    setForm((f) => ({ ...f, ...patch }));
246	    save.reset();
247	  };
248	
249	  const open = (p: Person) => {
250	    setForm({ name: p.name, grade: p.grade, gradeFrom: '', terms: p.terms === null ? '' : String(p.terms), contact: p.contact ?? '' });
251	    setEditing({ id: p.id, version: p.version });
252	    save.reset();
253	  };
254	
255	  const cancel = () => {
256	    setForm(EMPTY);
257	    setEditing(null);
258	    save.reset();
259	  };
260	
261	  // Everyone's due-total as their row shows it (null: n/a), and their names, by id.
262	  const everyone = people.data ?? [];
263	  const dueOf = new Map(everyone.map((q) => [q.id, personDue(
264	    liveClaims((claims.data ?? []).filter((c) => c.personId === q.id), [q]),
265	    rates.data, (d) => gradeOn(q, d), byGrade.get(q.grade), floor, charges, cap)]));
266	  const nameOf = new Map(everyone.map((q) => [q.id, q.name]));
267	
268	  return (
269	    <section>
270	      <h3>People</h3>
271	      <form
272	        onSubmit={(e) => {
273	          e.preventDefault();
274	          const v = { editing, input: form };
275	          submitOnce(() => {
276	            save.reset();
277	            return save.mutateAsync(v);
278	          });
279	        }}
280	      >
281	        <label>
282	          Name{' '}
283	          <input data-testid="person-form-name" value={form.name} onChange={(e) => change({ name: e.target.value })} />
284	        </label>{' '}
285	        <label>
286	          Grade{' '}
287	          <select data-testid="person-form-grade" value={form.grade} onChange={(e) => change({ grade: e.target.value })}>
288	            {GRADES.map((g) => (
289	              <option key={g} value={g}>
290	                {g}
291	              </option>
292	            ))}
293	          </select>
294	        </label>{' '}
295	        <label>
296	          from{' '}
297	          <input type="date" data-testid="person-form-grade-from" value={form.gradeFrom}
298	            onChange={(e) => change({ gradeFrom: e.target.value })} />
299	        </label>{' '}
300	        <label>
301	          Terms{' '}
302	          <input data-testid="person-form-terms" value={form.terms} placeholder="business days"
303	            onChange={(e) => change({ terms: e.target.value })} />
304	        </label>{' '}
305	        <label>
306	          Contact{' '}
307	          <input data-testid="person-form-contact" value={form.contact}
308	            onChange={(e) => change({ contact: e.target.value })} />
309	        </label>{' '}
310	        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
311	          {editing === null ? 'Add person' : 'Save person'}
312	        </button>
313	        {editing !== null && (
314	          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
315	            Cancel
316	          </button>
317	        )}
318	        {save.isError && (
319	          <span data-testid="person-form-error">
320	            {save.error instanceof HttpError && save.error.status === 409
321	              ? 'Someone else saved this person meanwhile: the form shows what is stored now. Open the editor again to edit it.'
322	              : 'A person needs a name and contact (if any) not already in use, and terms (if any) a whole number of days.'}
323	          </span>
324	        )}
325	      </form>
326	      <QuickAdd sheetId={sheetId} user={user} />
327	      <PasteClaims sheetId={sheetId} user={user} />
328	      <ShowRetired />{' '}
329	      <ExportPeople rows={() => everyone.map((p) => [p.name, gradeOn(p, today), p.retiredFrom ?? '', showDue(dueOf.get(p.id) ?? null)])} />
330	      <BulkOpen sheetId={sheetId} user={user} selected={[...selected]} onDone={() => setSelected(new Set())} />
331	      <BulkGrade sheetId={sheetId} user={user} selected={[...selectedPeople]} onDone={() => setSelectedPeople(new Set())} />
332	      <BulkSettle sheetId={sheetId} user={user} selected={[...selected]} onDone={() => setSelected(new Set())} />
333	      <BulkReassign sheetId={sheetId} user={user} selected={[...selected]} people={everyone}
334	        onDone={() => setSelected(new Set())} />
335	      {people.isError && <p data-testid="people-error">The people could not be loaded.</p>}
336	      <table>
337	        <tbody>
338	          {(people.data ?? []).filter((p) => showRetired || !p.retired).map((p) => {
339	            const own = (claims.data ?? []).filter((c) => c.personId === p.id);
340	            const live = liveClaims(own, [p]);
341	            const claimed = sumAmounts(live);
342	            const pct = byGrade.get(p.grade);
343	            const late = overdue(live, charges, (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges));
344	            const aged = agedDues(live, today, (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges));
345	            const split = splitDues(live, (c) => claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges));
346	            return (
347	              <tr key={p.id} data-testid={`person-row-${p.id}`}>
348	                <td>
349	                  <input type="checkbox" data-testid="person-select" checked={selectedPeople.has(p.id)}
350	                    onChange={(e) => selectPerson(p.id, e.target.checked)} />
351	                </td>
352	                <td data-testid="person-name">{p.name}</td>
353	                <td data-testid="person-grade">{p.grade}</td>
354	                <td>
355	                  Active <span data-testid="person-active">{isActive(live, today) ? 'yes' : 'no'}</span>
356	                </td>
357	                <td>
358	                  Terms <span data-testid="person-terms">{p.terms ?? ''}</span>
359	                </td>
360	                <td>
361	                  Contact <span data-testid="person-contact">{p.contact ?? ''}</span>
362	                </td>
363	                <td>
364	                  Claimed <span data-testid="person-claimed">{claimed}</span>
365	                </td>
366	                <td>
367	                  Due <span data-testid="person-due-total">{showDue(personDue(live, rates.data, (d) => gradeOn(p, d), pct, floor, charges, cap))}</span>{' '}
368	                  excess <span data-testid="person-excess">{excessOf(live, rates.data, (d) => gradeOn(p, d), pct, floor, charges, cap)}</span>
369	                </td>
370	                <td>
371	                  Settled <span data-testid="person-settled-total">{split.settled}</span>{' '}
372	                  open <span data-testid="person-open-total">{split.open}</span>
373	                </td>
374	                {(periods.data ?? []).map((q) => (
375	                  <td key={q.name}>
376	                    {q.name} <span data-testid={`person-period-${q.name}-due-total`}>
377	                      {personPeriodDue(q, p, claims.data ?? [], people.data, rates.data, floor, charges)}</span>
378	                  </td>
379	                ))}
380	                <td>
381	                  Aged 0-30 <span data-testid="person-aged-0-30">{aged.upTo30}</span>{' '}
382	                  31-60 <span data-testid="person-aged-31-60">{aged.upTo60}</span>{' '}
383	                  61+ <span data-testid="person-aged-61">{aged.over60}</span>
384	                </td>
385	                <td>
386	                  Overdue <span data-testid="person-overdue-count">{late.count}</span>{' '}
387	                  totalling <span data-testid="person-overdue-total">{late.total}</span>
388	                </td>
389	                <td>
390	                  <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => open(p)}>
391	                    Edit
392	                  </button>
393	                </td>
394	                <td>
395	                  <input type="date" data-testid="person-statement-asof" value={asOfDates[p.id] ?? ''}
396	                    onChange={(e) => {
397	                      setAsOfDates((d) => ({ ...d, [p.id]: e.target.value }));
398	                      statement.reset();
399	                    }} />{' '}
400	                  <button type="button" data-testid="person-statement" disabled={statement.isPending}
401	                    onClick={() => state(p.id)}>
402	                    Statement
403	                  </button>{' '}
404	                  <button type="button" data-testid="person-unstate" disabled={unstatement.isPending}
405	                    onClick={() => unstate(p.id)}>
406	                    Cancel statement
407	                  </button>{' '}
408	                  Statements <span data-testid="person-statement-count">{p.statementCount}</span>{' '}
409	                  last <span data-testid="person-stated-total">{p.statedTotal ?? ''}</span>{' '}
410	                  on <span data-testid="person-statement-date">{p.statementDate ?? ''}</span>
411	                  {statement.isError && statement.variables?.id === p.id && (
412	                    <span data-testid="person-error">The statement could not be taken.</span>
413	                  )}
414	                  {unstatement.isError && unstatement.variables === p.id && (
415	                    <span data-testid="person-error">The statement could not be cancelled: only a steward can, and only a statement there is.</span>
416	                  )}
417	                  {watching.isError && watching.variables?.id === p.id && (
418	                    <span data-testid="person-error">The person could not be watched.</span>
419	                  )}
420	                  {retirement.isError && retirement.variables?.id === p.id && (
421	                    <span data-testid="person-error">The person could not be retired: the date must be a date.</span>
422	                  )}
423	                  {holding.isError && holding.variables?.id === p.id && (
424	                    <span data-testid="person-error">The person could not be held: the dates must be dates, the to-date not before the from-date.</span>
425	                  )}
426	                  {aliasing.isError && aliasing.variables?.id === p.id && (
427	                    <span data-testid="person-error">The alias could not be added: it needs to be given, and not be a name or alias already in use.</span>
428	                  )}
429	                </td>
430	                <td>
431	                  Watched <span data-testid="person-watched">{watched.has(p.id) ? 'yes' : 'no'}</span>{' '}
432	                  <button type="button" data-testid="person-watch" disabled={watching.isPending || !watches.isSuccess}
433	                    onClick={() => watch(p.id, !watched.has(p.id))}>
434	                    {watched.has(p.id) ? 'Unwatch' : 'Watch'}
435	                  </button>
436	                </td>
437	                <td>
438	                  Retired <span data-testid="person-retired">{p.retired ? 'yes' : 'no'}</span>{' '}
439	                  from <span data-testid="person-retired-from">{p.retiredFrom ?? ''}</span>{' '}
440	                  <input type="date" data-testid="person-retire-date" value={retireDates[p.id] ?? ''}
441	                    onChange={(e) => {
442	                      setRetireDates((d) => ({ ...d, [p.id]: e.target.value }));
443	                      retirement.reset();
444	                    }} />{' '}
445	                  <button type="button" data-testid="person-retire" disabled={retirement.isPending}
446	                    onClick={() => retire(p.id)}>
447	                    Retire
448	                  </button>
449	                </td>
450	                <td>
451	                  On hold <span data-testid="person-hold">{p.held ? 'yes' : 'no'}</span>{' '}
452	                  {p.holds.map((h, i) => (
453	                    <span key={i} data-testid="person-hold-line">{h.from} to {h.to ?? '…'}; </span>
454	                  ))}
455	                  <input type="date" data-testid="person-hold-from" value={holdDates[p.id]?.from ?? ''}
456	                    onChange={(e) => changeHold(p.id, { from: e.target.value })} />{' '}
457	                  <input type="date" data-testid="person-hold-to" value={holdDates[p.id]?.to ?? ''}
458	                    onChange={(e) => changeHold(p.id, { to: e.target.value })} />{' '}
459	                  <button type="button" data-testid="person-hold-toggle" disabled={holding.isPending}
460	                    onClick={() => hold(p.id)}>
461	                    Hold
462	                  </button>
463	                </td>
464	                <td>
465	                  Aliases <span data-testid="person-aliases">{p.aliases.join(', ')}</span>{' '}
466	                  <input data-testid="person-alias-input" value={aliasInputs[p.id] ?? ''}
467	                    onChange={(e) => {
468	                      setAliasInputs((d) => ({ ...d, [p.id]: e.target.value }));
469	                      aliasing.reset();
470	                    }} />{' '}
471	                  <button type="button" data-testid="person-alias-add" disabled={aliasing.isPending}
472	                    onClick={() => alias(p.id)}>
473	                    Add alias
474	                  </button>
475	                </td>
476	                <td>
477	                  Patrons <span data-testid="person-patrons">
478	                    {p.patronIds.map((id) => nameOf.get(id) ?? '').sort((x, y) => x.localeCompare(y)).join(', ')}
479	                  </span>{' '}
480	                  backing <span data-testid="person-backing">{backing(claims.data ?? [], p.patronIds, today)}</span>{' '}
481	                  <select data-testid="person-patron-select" value={patronPicks[p.id] ?? ''}
482	                    onChange={(e) => {
483	                      setPatronPicks((d) => ({ ...d, [p.id]: e.target.value }));
484	                      patronage.reset();
485	                    }}>
486	                    <option value="">Patron…</option>
487	                    {everyone.filter((q) => q.id !== p.id).map((q) => (
488	                      <option key={q.id} value={String(q.id)}>
489	                        {q.name}
490	                      </option>
491	                    ))}
492	                  </select>{' '}
493	                  <button type="button" data-testid="person-patron-add" disabled={patronage.isPending}
494	                    onClick={() => patronize(p.id)}>
495	                    Add patron
496	                  </button>
497	                  {patronage.isError && patronage.variables?.id === p.id && (
498	                    <span data-testid="person-patron-error">The patron could not be added: not themselves, nor one already named.</span>
499	                  )}
500	                </td>
501	                <td>
502	                  <PersonClaims sheetId={sheetId} user={user} personId={p.id} claims={own} gradeOn={(d) => gradeOn(p, d)} rates={rates.data} floor={floor}
503	                    today={today} charges={charges} selected={selected} onSelect={select}
504	                    people={people.data ?? []} />
505	                </td>
506	              </tr>
507	            );
508	          })}
509	        </tbody>
510	      </table>
511	    </section>
512	  );
513	}

